// Stellar Oracle service worker (#361).
//
// Hand-written rather than generated by a build plugin, so no new build
// dependency is required. Registered only in production builds — see
// src/utils/registerServiceWorker.ts. Provides:
//   - An app-shell + offline-fallback cache for offline use.
//   - A cache-first runtime strategy for same-origin static assets.
//   - A controlled update flow: new versions install and wait until the
//     page explicitly asks them to activate (see PwaUpdateBanner.tsx),
//     so users are never silently switched to a new build mid-session.

const CACHE_VERSION = 'stellar-oracle-shell-v1'
const SCOPE_URL = new URL('.', self.location.href)
const OFFLINE_URL = new URL('offline.html', SCOPE_URL).href
const SHELL_URLS = [SCOPE_URL.href, OFFLINE_URL]

self.addEventListener('install', (event) => {
  event.waitUntil(caches.open(CACHE_VERSION).then((cache) => cache.addAll(SHELL_URLS)))
})

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) => Promise.all(keys.filter((key) => key !== CACHE_VERSION).map((key) => caches.delete(key))))
      .then(() => self.clients.claim()),
  )
})

self.addEventListener('message', (event) => {
  if (event.data?.type === 'SKIP_WAITING') {
    self.skipWaiting()
  }
})

self.addEventListener('fetch', (event) => {
  const request = event.request
  if (request.method !== 'GET') return

  if (request.mode === 'navigate') {
    event.respondWith(handleNavigate(request))
    return
  }

  if (new URL(request.url).origin === self.location.origin) {
    event.respondWith(handleAsset(request))
  }
})

async function handleNavigate(request) {
  try {
    return await fetch(request)
  } catch {
    const cache = await caches.open(CACHE_VERSION)
    const offline = await cache.match(OFFLINE_URL)
    return offline || Response.error()
  }
}

async function handleAsset(request) {
  const cache = await caches.open(CACHE_VERSION)
  const cached = await cache.match(request)
  if (cached) return cached

  try {
    const response = await fetch(request)
    if (response.ok) {
      cache.put(request, response.clone())
    }
    return response
  } catch {
    return Response.error()
  }
}
